import json,random
R=random.Random(7)
def Q(q,right,wrong,why,img=None):
    opts=[right]+wrong; R.shuffle(opts)
    d={"q":q,"options":opts,"answer":opts.index(right),"why":why}
    if img: d["img"]=img["src"]; d["alt"]=img["alt"]
    return d
def I(f,alt): return {"src":"assets/"+f,"alt":alt}
S={}
S["step-01"]={"title":"Step 1 — Offside, Properly","questions":[
 Q("An attacker's feet are exactly LEVEL with the second-last defender when the pass is played. What is the decision?","Onside",["Offside","Offside, but only if he scores","The referee must ask VAR"],"Level counts as onside. He must be nearer the goal line than the second-last opponent to be in an offside position."),
 Q("An attacker's body is behind the defender, but his outstretched arm is ahead of the defender. Offside?","No — arms and hands are not used to judge offside",["Yes — any part of the body counts","Yes, if the arm touches the ball","Only if the keeper complains"],"Only the head, body and feet count. Hands and arms are ignored."),
 Q("A throw-in is taken. The receiver is far beyond the last defender. What happens?","Play on — there is no offside from a throw-in",["Offside, indirect free kick","Offside only if he is past the keeper","The throw-in is retaken"],"You can't be offside directly from a goal kick, throw-in or corner."),
 Q("An attacker is in an offside position, but he does not touch the ball or affect any defender. The ball goes out of play. Offence?","No — being in an offside position is not an offence by itself",["Yes — the position is the offence","Yes, if he was nearer than 5 metres to a defender","Yes, but only inside the penalty area"],"The offence is being INVOLVED in active play, not just standing there.")]}
